 void code(ErrorCode code,org.junit.jupiter.api.function.Executable action){Throwable failure=cause(assertThrows(Exception.class,action));assertInstanceOf(TenantAccessException.class,failure);assertEquals(code,((TenantAccessException)failure).code());}
 @Test void actualSourceAuthoritiesAndBoundedGetRegisterAndReadExactOriginal()throws Exception{JsonNode receipt=f.register();assertEquals(1,f.registrations.size());String artifact=receipt.path("artifact").path("version_id").asText();var row=f.registrations.get(artifact);assertNull(row.projectId());assertEquals(f.original.reference(),f.artifactRows.get(artifact).reference());assertEquals(new String(f.served,StandardCharsets.UTF_8),row.canonicalDocument());assertEquals(List.of(new ArtifactRegistryProtocol.MemberRow(SOURCE,RIGHTS)),f.members.get(row.accessSetId()));assertEquals(receipt,f.service.read(f.subject,"1",artifact).path("receipt"));assertEquals(f.document(),f.service.read(f.subject,"1",artifact).path("document"));assertTrue(f.requests.get()>3);assertTrue(f.states.get()>f.requests.get());assertEquals(20,f.invoked.size());assertTrue(f.writes.indexOf("saveOperation")<f.writes.indexOf("insertRegistration"));assertTrue(f.writes.indexOf("saveAudit")<f.writes.indexOf("insertRegistration"));assertFalse(receipt.has("approved"));assertFalse(receipt.has("production_eligible"));assertFalse(receipt.has("evidence_class"));}
 @Test void originalKeyIsIdempotentAcrossRealSessionAndContextChanges()throws Exception{var receipt=f.register();int writes=f.writes.size();when(f.subject.sessionId()).thenReturn(id(31));when(f.admission.context()).thenReturn(new BusinessSessionProtocol.Context(TENANT,"2","1","1"));assertEquals(receipt,f.service.register(f.subject,"2",KEY,f.request()));assertEquals(writes,f.writes.size());var row=f.registrations.values().iterator().next();assertEquals(id(30),row.requestSession());assertEquals("1",row.requestContext());assertEquals(KEY,row.idempotencyKey());}
 @Test void typedOperationRecoveryUsesPersistedOriginalRequestAcrossSession()throws Exception{var receipt=f.register();when(f.subject.sessionId()).thenReturn(id(32));var read=f.service.recover(f.subject,"1",receipt.path("operation_id").asText());assertEquals(receipt,read.path("receipt"));assertEquals(f.document(),read.path("document"));}
